INSERT INTO `PaqueteTuristico` VALUES (8, 'Ruta Heroica y Valles del Pisco (Tacna + Moquegua)', 'Un viaje fascinante por la historia, los viñedos coloniales y las aguas termales relajantes del sur.', 890.00, '3 días / 2 noches', 'Incluye traslados interprovinciales y hospedaje seleccionado', 'PUBLICADO', 1, 15, '/img/tours/tacna_termales.jpg');
INSERT INTO `PaqueteTuristico` VALUES (9, 'Mar y Valle del Sur (Ilo + Moquegua)', 'Navegación con lobos marinos en Punta de Coles y descanso placentero en la campiña vitivinícola.', 599.98, '3 días / 2 noches', 'Incluye paseo en lancha y degustaciones artesanales', 'PUBLICADO', 1, 20, '/img/tours/ilo_punta_coles.jpg');
INSERT INTO `PaqueteTuristico` VALUES (10, 'Amazonía Profunda Tambopata (Madre de Dios)', 'Inmersión completa en la selva virgen con observación de fauna silvestre, canopy y navegación fluvial.', 1450.00, '4 días / 3 noches', 'Incluye ecolodge con pensión completa y guías nativos', 'PUBLICADO', 1, 25, '/img/tours/madrededios_sandoval.jpg');
INSERT INTO `PaqueteTuristico` VALUES (11, 'Expedición Andina y Bosque de Piedras (Pasco)', 'Explora las figuras de piedra más altas del mundo y navega en las aguas cristalinas de la Laguna Punrun.', 720.00, '2 días / 1 noche', 'Incluye transporte 4x4 y mate de coca', 'PUBLICADO', 1, 10, '/img/tours/pasco_huayllay.jpg');
INSERT INTO `PaqueteTuristico` VALUES (12, 'Lima Colonial y Sabores Criollos Express', 'Lo mejor de la capital: centros virreinales, templos coloniales, arte bohemio y la mejor gastronomía marina.', 550.00, '2 días / 1 noche', 'Incluye entradas y degustaciones gastronómicas', 'BORRADOR', 1, 0, '/img/tours/lima_colonial.jpg');
INSERT INTO `PaqueteTuristico` VALUES (17, 'Paquete de Prueba Verificacion 2', 'Paquete de prueba 2', 150.00, '4 dias', 'ninguna', 'PUBLICADO', 1, 5, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=600&auto=format&fit=crop');
