INSERT INTO `ServicioTuristico` VALUES (52, 'City Tour Lima Colonial y Catacumbas', 'Recorrido por la Plaza Mayor, Palacio de Gobierno, Catedral y criptas subterráneas de San Francisco, terminando en el Malecón de Miraflores.', NULL, 95.00, NULL, NULL, 'ACTIVO', '2026-09-30T04:22:40', 1, 2);
INSERT INTO `ServicioTuristico` VALUES (53, 'Ruta Gastronómica y Bohemia en Barranco', 'Caminata por el barrio bohemio de Barranco, Puente de los Suspiros, Bajada de Baños y cata de café peruano con degustación de platos criollos.', NULL, 110.00, NULL, NULL, 'ACTIVO', '2026-09-30T04:22:40', 1, 2);
INSERT INTO `ServicioTuristico` VALUES (54, 'Expedición Bosque de Piedras de Huayllay', 'Caminata por una de las maravillas geológicas del Perú a más de 4000 msnm. Figuras rocosas de animales prehistóricos y baño en aguas termales de La Calera.', NULL, 160.00, NULL, NULL, 'ACTIVO', '2026-09-30T04:22:40', 1, 3);
INSERT INTO `ServicioTuristico` VALUES (55, 'Laguna Punrun y Rutas Andinas de Pasco', 'Navegación en bote por la inmensa Laguna Punrun, avistamiento de aves altoandinas (flamencos y parihuanas) y visita a comunidades tradicionales.', NULL, 140.00, NULL, NULL, 'ACTIVO', '2026-09-30T04:22:40', 1, 3);
INSERT INTO `ServicioTuristico` VALUES (56, 'Ruta Heroica y Aguas Termales de Calientes Tacna', 'Visita al histórico Campo del Alto de la Alianza, complejo arqueológico de Miculla con sus puentes colgantes y relajante circuito en pozas termales medicinales.', NULL, 130.00, NULL, NULL, 'ACTIVO', '2026-09-30T04:22:40', 1, 7);
INSERT INTO `ServicioTuristico` VALUES (57, 'Circuito Valle Viejo y Viñedos de Pocollay', 'Tour por la campiña tacneña, casonas coloniales de Calana y Pachía, degustación de pisco tacneño, macerados de damasco y almuerzo de pastel de choclo.', NULL, 100.00, NULL, NULL, 'ACTIVO', '2026-09-30T04:22:40', 1, 7);
INSERT INTO `ServicioTuristico` VALUES (58, 'Inmersión Reserva Tambopata y Lago Sandoval', 'Expedición en bote por el río Madre de Dios y caminata en selva virgen. Observación de lobos gigantes de río, monos aulladores, perezosos y caimanes.', NULL, 290.00, NULL, NULL, 'ACTIVO', '2026-09-30T04:22:40', 1, 6);
INSERT INTO `ServicioTuristico` VALUES (59, 'Aventura Río Madre de Dios y Collpa de Loros', 'Canopy walkway sobre las copas de los árboles amazónicos a 35 metros de altura, kayak por el río y espectáculo multicolor matutino de loros y guacamayos.', NULL, 230.00, NULL, NULL, 'ACTIVO', '2026-09-30T04:22:40', 1, 6);
INSERT INTO `ServicioTuristico` VALUES (60, 'Aventura Marina en Reserva Punta de Coles Ilo', 'Navegación costera en lancha rápida hacia la reserva marina. Avistamiento de cientos de lobos marinos chuscos y finos, pingüinos de Humboldt y aves guaneras.', NULL, 145.00, NULL, NULL, 'ACTIVO', '2026-09-30T04:22:40', 1, 5);
INSERT INTO `ServicioTuristico` VALUES (61, 'Circuito Costero Playas de Ilo y Malecón', 'Día de sol y brisa en las paradisíacas playas Puerto Inglés y Pozo de Lis. Vista fotográfica en la Glorieta José Gálvez y degustación de mariscos frescos.', NULL, 90.00, NULL, NULL, 'ACTIVO', '2026-09-30T04:22:40', 1, 5);
INSERT INTO `ServicioTuristico` VALUES (62, 'Ruta Colonial del Vino y Campiñas de Moquegua', 'Paseo por las tradicionales bodegas pisqueras coloniales (Biondi, Rayito de Sol), cata de vinos aromáticos y recorrido arquitectónico por casonas con techos de mojinete.', NULL, 120.00, NULL, NULL, 'ACTIVO', '2026-09-30T04:22:40', 1, 4);
INSERT INTO `ServicioTuristico` VALUES (63, 'Expedición Valle de Torata y Cataratas de Mollesaja', 'Descubre los molinos coloniales de Torata, la repostería artesanal moqueguana (roscas de manteca) y la hermosa caída de agua de Mollesaja en un valle fértil.', NULL, 135.00, NULL, NULL, 'ACTIVO', '2026-09-30T04:22:40', 1, 4);
