INSERT INTO `Tour` VALUES (3, 2, 'valle-sagrado', 'Valle Sagrado de los Incas', 'Historia y paisajes.', 320.00, 220.00, 90.00, '1 día', 'Cusco', 'Cultura', 4.60, 'ACTIVO', 1, 'false', NULL, NULL, 1, 6);
INSERT INTO `Tour` VALUES (52, 7, 'city-tour-lima-colonial-y-catacumbas', 'City Tour Lima Colonial y Catacumbas', 'Plaza Mayor, Palacio de Gobierno, Catedral y criptas subterráneas de San Francisco.', 95.00, 55.00, 0.00, '5 horas', NULL, 'Cultural', 5.00, 'ACTIVO', 2, 'true', 'Transporte turístico climatizado, Guía oficial bilingüe, Entrada a Catacumbas, Seguro de viaje', 'Almuerzo, Propinas, Gastos personales', 1, 5);
INSERT INTO `Tour` VALUES (53, 7, 'ruta-gastron-mica-y-bohemia-en-barranco', 'Ruta Gastronómica y Bohemia en Barranco', 'Puente de los Suspiros, Bajada de Baños y cata de cafés de especialidad y comida criolla.', 110.00, 65.00, 0.00, '4 horas', NULL, 'Descanso', 5.00, 'ACTIVO', 2, 'true', 'Degustación de 4 platos criollos, Tostaduría de café especial, Guía turístico gastronómico', 'Bebidas alcohólicas adicionales, Souvenirs', 1, 4);
INSERT INTO `Tour` VALUES (54, 3, 'expedici-n-bosque-de-piedras-de-huayllay', 'Expedición Bosque de Piedras de Huayllay', 'Caminata entre figuras rocosas milenarias a más de 4000 msnm y baños termales de La Calera.', 160.00, 95.00, 0.00, '1 día', NULL, 'Aventura', 5.00, 'ACTIVO', 3, 'false', 'Movilidad privada 4x4, Guía de alta montaña, Ticket de ingreso a Huayllay y Baños Termales, Box lunch andino', 'Ropa de abrigo, Desayuno, Propinas', 1, 8);
INSERT INTO `Tour` VALUES (55, 3, 'laguna-punrun-y-rutas-andinas-de-pasco', 'Laguna Punrun y Rutas Andinas de Pasco', 'Navegación en bote por la inmensa laguna Punrun con avistamiento de aves altoandinas.', 140.00, 80.00, 0.00, '7 horas', NULL, 'Naturaleza', 5.00, 'ACTIVO', 3, 'false', 'Transporte rural, Paseo en bote con chaleco salvavidas, Guía local comunitario, Mate de coca para altura', 'Almuerzo campestre, Gastos personales', 1, 7);
INSERT INTO `Tour` VALUES (56, 6, 'ruta-heroica-y-aguas-termales-de-calientes-tacna', 'Ruta Heroica y Aguas Termales de Calientes Tacna', 'Campo del Alto de la Alianza, petroglifos de Miculla y pozas termales medicinales.', 130.00, 75.00, 0.00, '6 horas', NULL, 'Descanso', 5.00, 'ACTIVO', 7, 'true', 'Movilidad turística, Entrada al Museo Alto de la Alianza y Baños Termales, Guía especializado, Seguro SOAT turístico', 'Toallas, Ropa de baño, Almuerzo típico', 1, 6);
INSERT INTO `Tour` VALUES (57, 6, 'circuito-valle-viejo-y-vi-edos-de-pocollay', 'Circuito Valle Viejo y Viñedos de Pocollay', 'Paseo campestre, casonas coloniales, degustación de piscos tacneños y macerados de damasco.', 100.00, 60.00, 0.00, '5 horas', NULL, 'Cultural', 5.00, 'ACTIVO', 7, 'true', 'Transporte privado, Cata en 2 bodegas pisqueras artesanales, Guía local, Bocadillos regionales', 'Almuerzo a la carta, Compras de botellas de pisco', 1, 5);
INSERT INTO `Tour` VALUES (58, 5, 'inmersi-n-reserva-tambopata-y-lago-sandoval', 'Inmersión Reserva Tambopata y Lago Sandoval', 'Expedición en bote por el río Madre de Dios, lobos gigantes de río, perezosos y caimanes.', 290.00, 180.00, 0.00, '2 días', NULL, 'Naturaleza', 5.00, 'ACTIVO', 6, 'false', 'Traslado fluvial en canoa motorizada, Boleto SERNANP Tambopata, Alojamiento ecológico 1 noche, Alimentación completa amazónica, Botas de jebe', 'Bebidas enlatadas, Pasajes aéreos a Puerto Maldonado', 2, 24);
INSERT INTO `Tour` VALUES (59, 5, 'aventura-r-o-madre-de-dios-y-collpa-de-loros', 'Aventura Río Madre de Dios y Collpa de Loros', 'Canopy walkway sobre la selva a 35m de altura y espectáculo matutino de guacamayos.', 230.00, 140.00, 0.00, '8 horas', NULL, 'Aventura', 5.00, 'ACTIVO', 6, 'false', 'Equipos certificados de canopy y tirolina, Embarcación con motor fuera de borda, Desayuno a bordo, Guía naturalista con telescopio', 'Propinas para boteros, Bebidas gaseosas', 1, 8);
INSERT INTO `Tour` VALUES (60, 7, 'aventura-marina-en-reserva-punta-de-coles-ilo', 'Aventura Marina en Reserva Punta de Coles Ilo', 'Lancha rápida hacia la reserva marina, avistamiento de cientos de lobos marinos y pingüinos.', 145.00, 85.00, 0.00, '5 horas', NULL, 'Aventura', 5.00, 'ACTIVO', 5, 'true', 'Paseo marítimo guiado, Chalecos salvavidas certificados, Tasa portuaria, Guía turístico marino', 'Pastillas para el mareo, Almuerzo marino', 1, 5);
INSERT INTO `Tour` VALUES (61, 7, 'circuito-costero-playas-de-ilo-y-malec-n', 'Circuito Costero Playas de Ilo y Malecón', 'Playas Puerto Inglés y Pozo de Lis, Glorieta José Gálvez y ceviche en el puerto.', 90.00, 50.00, 0.00, '6 horas', NULL, 'Descanso', 5.00, 'ACTIVO', 5, 'true', 'Movilidad ejecutiva ida y vuelta a playas, Sombrilla playera instalada, Guía acompañante', 'Consumos en restaurantes playeros, Deportes acuáticos extras', 1, 6);
INSERT INTO `Tour` VALUES (62, 6, 'ruta-colonial-del-vino-y-campi-as-de-moquegua', 'Ruta Colonial del Vino y Campiñas de Moquegua', 'Bodegas pisqueras coloniales, cata de vinos y casonas históricas con techos de mojinete.', 120.00, 70.00, 0.00, '5 horas', NULL, 'Cultural', 5.00, 'ACTIVO', 4, 'true', 'Transporte turístico, Entrada a 3 bodegas tradicionales, Degustación guiada de pisco y macerados, Guía oficial', 'Almuerzo campestre, Compras personales', 1, 5);
INSERT INTO `Tour` VALUES (63, 6, 'expedici-n-valle-de-torata-y-cataratas-de-mollesaja', 'Expedición Valle de Torata y Cataratas de Mollesaja', 'Molinos coloniales, repostería artesanal moqueguana y hermosa cascada en valle fértil.', 135.00, 80.00, 0.00, '7 horas', NULL, 'Naturaleza', 5.00, 'ACTIVO', 4, 'true', 'Movilidad turística, Visita a molinos de piedra, Degustación de panes torateños, Caminata guiada a cataratas', 'Almuerzo, Ropa de recambio', 1, 7);
INSERT INTO `Tour` VALUES (65, 1, 'camino-inca-cl-sico-4d-3n', 'Camino Inca Clásico 4D/3N', 'Trek legendario por el Qhapaq Ñan hacia la ciudadela sagrada de Machu Picchu.', 850.00, 550.00, 0.00, '4 días', NULL, 'Aventura', 5.00, 'ACTIVO', 1, 'false', NULL, NULL, 1, 6);
INSERT INTO `Tour` VALUES (66, 1, 'tour-maras-moray-y-salineras', 'Tour Maras Moray y Salineras', 'Visita los andenes circulares concéntricos de Moray y las impresionantes pozas de sal de Maras.', 120.00, 70.00, 0.00, '5 horas', NULL, 'Cultural', 5.00, 'ACTIVO', 1, 'false', NULL, NULL, 1, 6);
INSERT INTO `Tour` VALUES (67, 1, 'expedici-n-andina-cusco-arqueol-gico', 'Expedición Andina Cusco Arqueológico', 'Recorrido por Sacsayhuamán, Qenqo, Puka Pukara y Tambomachay.', 95.00, 55.00, 0.00, '4 horas', NULL, 'Cultural', 5.00, 'ACTIVO', 1, 'false', NULL, NULL, 1, 6);
INSERT INTO `Tour` VALUES (69, 2, 'machu-picchu-m-gico-full-day', 'Machu Picchu Mágico Full Day', 'Viaje panorámico en tren Expedition o Voyager y visita guiada a la maravilla del mundo.', 650.00, 420.00, 0.00, '1 día', NULL, 'Cultural', 5.00, 'ACTIVO', 1, 'false', NULL, NULL, 1, 6);
INSERT INTO `Tour` VALUES (70, 2, 'monta-a-de-7-colores-vinicunca', 'Montaña de 7 Colores Vinicunca', 'Caminata de alta montaña hacia la cumbre arcoíris con vistas del nevado Ausangate.', 180.00, 110.00, 0.00, '1 día', NULL, 'Aventura', 5.00, 'ACTIVO', 1, 'false', NULL, NULL, 1, 6);
INSERT INTO `Tour` VALUES (71, 2, 'laguna-humantay-aventura-trek', 'Laguna Humantay Aventura & Trek', 'Excursión a la laguna turquesa a los pies del imponente glaciar Salkantay.', 160.00, 95.00, 0.00, '1 día', NULL, 'Naturaleza', 5.00, 'ACTIVO', 1, 'false', NULL, NULL, 1, 6);
INSERT INTO `Tour` VALUES (72, 3, 'tour-ba-os-termales-y-cascada-la-calera', 'Tour Baños Termales y Cascada La Calera', 'Circuito terapéutico en aguas termominerales rodeado de imponentes paisajes andinos.', 85.00, 50.00, 0.00, '5 horas', NULL, 'Descanso', 5.00, 'ACTIVO', 3, 'false', NULL, NULL, 1, 6);
INSERT INTO `Tour` VALUES (73, 3, 'ruta-arqueol-gica-huarautambo', 'Ruta Arqueológica Huarautambo', 'Visita al puente inca y complejo arqueológico de la cultura Yarush.', 110.00, 65.00, 0.00, '6 horas', NULL, 'Cultural', 5.00, 'ACTIVO', 3, 'false', NULL, NULL, 1, 6);
INSERT INTO `Tour` VALUES (74, 5, 'tour-nocturno-caimanes-y-selva-virgen', 'Tour Nocturno Caimanes y Selva Virgen', 'Safari fluvial nocturno en canoa motorizada buscando caimanes blancos y capibaras.', 150.00, 90.00, 0.00, '4 horas', NULL, 'Aventura', 5.00, 'ACTIVO', 6, 'false', NULL, NULL, 1, 6);
